begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('99000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer,org integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated','org_id',pg_temp.id(org))::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'event-'||n||'@test.local' from generate_series(10,16) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'event-a','Events A'),(pg_temp.id(2),'event-b','Events B');
insert into public.memberships(organization_id,user_id,role) values
 (pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'viewer'),(pg_temp.id(1),pg_temp.id(12),'branch_user'),
 (pg_temp.id(2),pg_temp.id(13),'owner'),(pg_temp.id(1),pg_temp.id(14),'planner'),(pg_temp.id(1),pg_temp.id(15),'approver'),(pg_temp.id(1),pg_temp.id(16),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone)
 select pg_temp.id(20+n),pg_temp.id(case when n=2 then 2 else 1 end),'L'||n,'Location','branch','SA','Asia/Riyadh' from generate_series(0,2) n;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(21));
insert into public.planning_runs(id,organization_id,location_id,request_id,from_date,to_date,kind,status,options,finished_at,result)
 select pg_temp.id(30+n),pg_temp.id(case when n=2 then 2 else 1 end),pg_temp.id(20+n),pg_temp.id(40+n),
 '2026-01-01','2026-10-10','forecast','succeeded','{"method":"expanded-v1"}',now(),'{}' from generate_series(0,2) n;
insert into public.forecast_results(id,organization_id,run_id,location_id,item_id,item_code,item_name,status,model,summary,evidence)
 select pg_temp.id(50+n),pg_temp.id(case when n=2 then 2 else 1 end),pg_temp.id(30+n),pg_temp.id(20+n),pg_temp.id(60+n),'ITEM','Saved item','selected','mean',
 '{"total":"3.003","scores":[]}',
 '{"source":{"start_day":"2026-01-01","end_day":"2026-10-10","introduced_on":null,"discontinued_on":null,"demand":[],"unit_provenance":{"method":"source-units-v1","status":"consistent","unit":"EA","rows":1,"unknown_rows":0,"units":["EA"]}},"output":{"status":"selected","model":"mean","total":"3.003","scores":[],"folds":[],"forecast":[{"date":"2026-10-11","quantity":"1.001"},{"date":"2026-10-12","quantity":"2.002"}],"uncertainty":{"status":"available","bands":[{"lower80":"0","upper80":"2","lower95":"0","upper95":"3"},{"lower80":"0","upper80":"3","lower95":"0","upper95":"4"}]}}}' from generate_series(0,2) n;
create temporary table fixture as select evidence baseline from public.forecast_results where id=pg_temp.id(50);
alter table fixture add report jsonb;
alter table fixture add saved uuid;
grant all on fixture to authenticated;
create function pg_temp.preview(additions jsonb default '[{"date":"2026-10-11","quantity":"0.009"}]',unit text default 'EA',confirmed boolean default true)
 returns jsonb language sql as $$select public.planned_event_preview(pg_temp.id(1),pg_temp.id(50),'campaign','Launch','Incremental demand',unit,additions,confirmed)$$;
create function pg_temp.save(request integer default 70,confirmed boolean default true,fp text default null) returns uuid language sql as $$
 select public.planned_event_save(pg_temp.id(1),pg_temp.id(50),'campaign','Launch','Incremental demand','EA','[{"date":"2026-10-11","quantity":"0.009"}]',confirmed,pg_temp.id(request),coalesce(fp,(select report->>'fingerprint' from fixture)))$$;
select pg_temp.login(10,1);
set local role authenticated;
select is(public.planned_event_source(pg_temp.id(1),pg_temp.id(50))->>'status','available','selected known-unit forecast available');
update fixture set report=pg_temp.preview();
select is((select report#>>'{totals,baseline}' from fixture),'3.003','exact baseline sum');
select is((select report#>>'{totals,addition}' from fixture),'0.009','exact addition sum');
select is((select report#>>'{totals,adjusted}' from fixture),'3.012','exact adjusted sum');
select is((select report#>>'{daily,0,adjusted}' from fixture),'1.01','decimal addition without binary rounding');
select is((select report#>>'{daily,1,addition}' from fixture),'0','unlisted date receives zero addition');
select is((select report#>'{source,evidence}' from fixture),(select baseline from fixture),'complete baseline evidence copied unchanged');
select is(pg_temp.preview('[{"date":"2026-10-12","quantity":"0"}]')#>>'{totals,adjusted}','3.003','zero scenario permitted');
select is(pg_temp.preview('[{"date":"2026-10-11","quantity":"999999999999999.999"}]')#>>'{totals,adjusted}','1000000000000003.002','full numeric(18,3) precision retained');
select is(pg_temp.preview('[{"date":"2026-10-11","quantity":"00.009"}]')->>'fingerprint',(select report->>'fingerprint' from fixture),'numeric-equivalent inputs canonicalized');
select is(pg_temp.preview('[{"date":"2026-10-11","quantity":"1"}]','EA',false)#>>'{input,confirmed}','false','unconfirmed preview can be inspected');
select throws_ok($$select pg_temp.save(70,false)$$,'MQ422','invalid event save','confirmation required to save');
select throws_ok($$select pg_temp.preview('[]')$$,'MQ422','invalid event additions','empty input rejected');
select throws_ok($$select pg_temp.preview('null')$$,'MQ422','invalid event input','null array rejected');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":"-1"}]')$$,'MQ422','invalid event addition','negative additions rejected');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":"0.0001"}]')$$,'MQ422','invalid event addition','excess precision not rounded silently');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":"1e4"}]')$$,'MQ422','invalid event addition','exponent rejected');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":1}]')$$,'MQ422','invalid event addition','decimal JSON strings required');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":null}]')$$,'MQ422','invalid event addition','null quantity rejected');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":"1000000000000000"}]')$$,'MQ422','invalid event addition','oversized addition rejected');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":"1"},{"date":"2026-10-11","quantity":"2"}]')$$,'MQ422','duplicate event dates','duplicate dates rejected');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-10","quantity":"1"}]')$$,'MQ422','event unit or dates incompatible','cutoff date outside future horizon');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-13","quantity":"1"}]')$$,'MQ422','event unit or dates incompatible','date after horizon rejected');
select throws_ok($$select pg_temp.preview('[{"date":"2026-02-30","quantity":"1"}]')$$,'MQ422','event unit or dates incompatible','invalid calendar date rejected without database exception');
select throws_ok($$select pg_temp.preview('[{"date":"2026-10-11","quantity":"1"}]','SET')$$,'MQ422','event unit or dates incompatible','unit mismatch rejected');
select throws_ok($$select public.planned_event_preview(pg_temp.id(1),pg_temp.id(50),'tender','','Reason','EA','[{"date":"2026-10-11","quantity":"1"}]',true)$$,'MQ422','invalid event input','name required');
select throws_ok($$select public.planned_event_preview(pg_temp.id(1),pg_temp.id(50),'recall','Recall','   ','EA','[{"date":"2026-10-11","quantity":"1"}]',true)$$,'MQ422','invalid event input','reason required');
update fixture set saved=pg_temp.save();
select is(pg_temp.save(),(select saved from fixture),'identical retry returns original');
select throws_ok($$select pg_temp.save(70,true,repeat('a',64))$$,'MQ409','event request conflicts','conflicting request refused');
select throws_ok($$select pg_temp.save(71,true,repeat('a',64))$$,'MQ409','event evidence changed; refresh preview','forged fingerprint refused');
select is((select count(*)::integer from public.planned_event_scenarios),1,'one scenario persisted');
select is((select evidence from public.forecast_results where id=pg_temp.id(50)),(select baseline from fixture),'save never changes original forecast');
select is((select count(*)::integer from public.inventory_policies where organization_id=pg_temp.id(1)),0,'save creates no policy');
select is((select count(*)::integer from public.replenishment_drafts where organization_id=pg_temp.id(1)),0,'save creates no replenishment draft');
select is((select count(*)::integer from public.open_orders where organization_id=pg_temp.id(1)),0,'save creates no inbound order');
select throws_ok($$delete from public.planned_event_scenarios$$,'42501',null,'direct delete forbidden');
select throws_ok($$update public.planned_event_scenarios set name='Changed'$$,'42501',null,'direct update forbidden');
select throws_ok($$insert into public.planned_event_scenarios default values$$,'42501',null,'direct insert forbidden');
select throws_ok($$select public.planned_event_source(pg_temp.id(2),pg_temp.id(52))$$,'MQ404','event source unavailable','cross-tenant source denied');
select pg_temp.login(11,1);
select is((select count(*)::integer from public.planned_event_scenarios),1,'viewer can inspect saved scenarios');
select lives_ok($$select pg_temp.preview()$$,'viewer can inspect RPC preview');
select throws_ok($$select pg_temp.save()$$,'MQ403','event save forbidden','viewer cannot save even on retry');
select pg_temp.login(15,1);
select throws_ok($$select pg_temp.save(72)$$,'MQ403','event save forbidden','approver cannot save');
select pg_temp.login(12,1);
select is((select count(*)::integer from public.planned_event_scenarios),0,'branch user cannot inspect other location');
select throws_ok($$select pg_temp.preview()$$,'MQ404','event source unavailable','definer preview preserves branch scope');
select lives_ok($$select public.planned_event_source(pg_temp.id(1),pg_temp.id(51))$$,'branch reads permitted source');
select pg_temp.login(13,2);
select is((select count(*)::integer from public.planned_event_scenarios),0,'other tenant sees no history');
select throws_ok($$select pg_temp.save()$$,'MQ403','event save forbidden','other tenant cannot replay request');
select pg_temp.login(10,2);
select throws_ok($$select pg_temp.preview()$$,'MQ404','event source unavailable','active organization claim narrows owner');
reset role;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(20));
select pg_temp.login(12,1);set local role authenticated;
select is((select count(*)::integer from public.planned_event_scenarios),1,'branch reads history after permission granted');
reset role;
update public.forecast_results set evidence=jsonb_set(evidence,'{source,unit_provenance,status}','"unknown"') where id=pg_temp.id(50);
select pg_temp.login(10,1);set local role authenticated;
select is(public.planned_event_source(pg_temp.id(1),pg_temp.id(50))->>'status','unit_unknown','missing unit evidence unavailable');
select throws_ok($$select pg_temp.preview()$$,'MQ422','event source incompatible','unknown-unit source cannot be used');
select is(pg_temp.save(),(select saved from fixture),'historical retry retains saved evidence');
select is((select report#>>'{source,evidence,source,unit_provenance,status}' from public.planned_event_scenarios),'consistent','history remains immutable');
reset role;
update public.forecast_results set evidence=jsonb_set((select baseline from fixture),'{source,preparation}','{}') where id=pg_temp.id(50);
select pg_temp.login(10,1);set local role authenticated;
select is(public.planned_event_source(pg_temp.id(1),pg_temp.id(50))->>'status','prepared_group','prepared group excluded');
reset role;
update public.forecast_results set evidence=(select baseline from fixture) where id=pg_temp.id(50);
update public.planning_runs set kind='policy' where id=pg_temp.id(30);
set local role authenticated;
select is(public.planned_event_source(pg_temp.id(1),pg_temp.id(50))->>'status','forecast_unavailable','non-forecast run excluded');
reset role;
update public.planning_runs set kind='forecast' where id=pg_temp.id(30);
update public.forecast_results set evidence=jsonb_set(evidence,'{output,forecast,0,date}','"2026-10-12"') where id=pg_temp.id(50);
set local role authenticated;
select is(public.planned_event_source(pg_temp.id(1),pg_temp.id(50))->>'status','source_invalid','broken daily horizon unavailable');
reset role;
update public.forecast_results set evidence=(select baseline from fixture) where id=pg_temp.id(50);
select pg_temp.login(14,1);set local role authenticated;
select lives_ok($$select pg_temp.save(80)$$,'planner can save independent scenario');
select is((select report#>>'{totals,adjusted}' from public.planned_event_scenarios where request_id=pg_temp.id(80)),'3.012','scenarios do not stack automatically');
select pg_temp.login(16,1);
select lives_ok($$select pg_temp.save(81)$$,'admin can save');
reset role;
select is((select count(*)::integer from public.audit_log where organization_id=pg_temp.id(1) and table_name='planned_event_scenarios'),3,'one audit per new scenario, none for retries');
set local role anon;
select throws_ok($$select * from public.planned_event_scenarios$$,'42501',null,'anonymous cannot read history');
select throws_ok($$select public.planned_event_source(pg_temp.id(1),pg_temp.id(50))$$,'42501',null,'anonymous cannot call source');
reset role;
select * from finish();
rollback;
